## Design Note

A single-pass character-driven state machine tracks one top-level value at a time. States: BETWEEN, TOP_STRING, TOP_CONTAINER, TOP_NUMBER, TOP_LITERAL. The container scanner uses a stack of (type, cstate) tuples plus flags for in-string/in-number/in-literal to validate nesting, commas, colons, and number/literal syntax incrementally. Each character is consumed exactly once; the current value's text is appended to a list and joined+decoded via `json.loads` only when the value boundary is confirmed. Top-level numbers/literals require a valid terminator char before being emitted. Total work is O(n) in characters fed, with O(1) per-character overhead. No concurrency needed (single-connection use).

### solution.py
```python
"""Incremental JSON stream splitter for log ingestion."""

import json

class JSONStreamError(ValueError):
    def __init__(self, msg="", offset=0):
        super().__init__(msg)
        self.offset = offset

class IncompleteJSONError(JSONStreamError):
    pass

class BufferLimitError(JSONStreamError):
    pass

# ── constants ──────────────────────────────────────────────────────────────
_WS = frozenset(' \t\n\r')
_DIGIT = frozenset('0123456789')
_NONZERO = frozenset('123456789')
_HEX = frozenset('0123456789abcdefABCDEF')
_ESC_CHARS = frozenset('"\\/bfnrtu')

# number sub-states
_N = ('START','NEG','ZERO','INT','DOT','FRAC','EXP','EXPS','EXPD')
_N_CAN_END = frozenset({2,3,5,8})  # ZERO, INT, FRAC, EXPD

# container structural states
_C_FIRST, _C_COLON, _C_VALUE, _C_SEP = 0, 1, 2, 3

# value-kind tags inside container
_VK_NUM, _VK_LIT, _VK_STR, _VK_CONT = 'num', 'lit', 'str', 'cont'

# literal targets
_LITS = {'t': 'true', 'f': 'false', 'n': 'null'}

# valid terminators for top-level number/literal
_TERM = frozenset(' \t\n\r{["')


class JSONStreamDecoder:
    def __init__(self, *, max_buffer: int = 10_000_000) -> None:
        if not isinstance(max_buffer, int) or isinstance(max_buffer, bool) or max_buffer < 1:
            raise ValueError("max_buffer must be an int >= 1")
        self.max_buffer = max_buffer
        self._pos = 0          # absolute char offset (next char to process)
        self._errored = False
        self._closed = False
        # main state: BETWEEN, TS, TC, TN, TL
        self._st = 'BETWEEN'
        # value buffer
        self._buf: list[str] = []
        self._vstart = 0       # absolute offset of value's first char
        # string scanner (shared by top-level and container strings)
        self._ss = 0           # 0=content 1=escape 2=unicode
        self._ur = 0           # unicode hex digits remaining
        # number scanner
        self._ns = 0           # index into _N
        # literal scanner
        self._lt: str | None = None
        self._lp = 0
        # container scanner
        self._stk: list[tuple[bool, int]] = []  # (is_object, cstate)
        self._ins = False      # inside a string within container
        self._vk: str | None = None  # current value kind in container
        # top-level number/literal waiting for terminator
        self._wt = False

    # ── public API ─────────────────────────────────────────────────────────
    def feed(self, chunk: str) -> list:
        if self._errored:
            raise JSONStreamError("decoder in error state", self._pos)
        if self._closed:
            raise JSONStreamError("decoder is closed", self._pos)
        if not isinstance(chunk, str):
            raise TypeError(f"expected str, got {type(chunk).__name__}")
        if not chunk:
            return []
        results: list = []
        for ch in chunk:
            self._tick(ch, results)
        return results

    def close(self) -> list:
        if self._errored:
            raise JSONStreamError("decoder in error state", self._pos)
        if self._closed:
            raise JSONStreamError("decoder is closed", self._pos)
        self._closed = True
        st = self._st
        if st == 'BETWEEN':
            return []
        if st == 'TN' or st == 'TL':
            if self._wt:
                # complete number/literal, emit it
                val = self._decode_buf()
                self._reset_value()
                return [val]
            raise IncompleteJSONError("incomplete value at end of stream", self._pos)
        # TC or TS or in-container sub-state → incomplete
        raise IncompleteJSONError("incomplete value at end of stream", self._pos)

    def pending(self) -> int:
        if self._st == 'BETWEEN':
            return 0
        return len(self._buf)

    # ── internals ──────────────────────────────────────────────────────────
    def _err(self, ch: str, offset: int | None = None):
        self._errored = True
        raise JSONStreamError(
            f"invalid JSON at offset {offset if offset is not None else self._pos}: {ch!r}",
            offset if offset is not None else self._pos,
        )

    def _buf_err(self, ch: str):
        self._errored = True
        raise BufferLimitError(
            f"value exceeds max_buffer={self.max_buffer}",
            self._vstart + self.max_buffer,
        )

    def _add(self, ch: str):
        self._buf.append(ch)
        if len(self._buf) > self.max_buffer:
            self._buf_err(ch)

    def _decode_buf(self):
        text = ''.join(self._buf)
        return json.loads(text)

    def _reset_value(self):
        self._buf = []
        self._st = 'BETWEEN'
        self._wt = False
        self._stk = []
        self._ins = False
        self._vk = None
        self._ss = 0
        self._ur = 0
        self._ns = 0
        self._lt = None
        self._lp = 0

    # ── main tick ──────────────────────────────────────────────────────────
    def _tick(self, ch: str, results: list):
        pos = self._pos
        self._pos += 1
        st = self._st

        if st == 'BETWEEN':
            self._between(ch, pos, results)
        elif st == 'TS':
            self._top_str(ch, pos, results)
        elif st == 'TC':
            self._top_cont(ch, pos, results)
        elif st == 'TN':
            self._top_num(ch, pos, results)
        elif st == 'TL':
            self._top_lit(ch, pos, results)

    # ── BETWEEN ────────────────────────────────────────────────────────────
    def _between(self, ch: str, pos: int, results: list):
        if ch in _WS:
            return
        if ch == '"':
            self._vstart = pos
            self._buf = []
            self._add(ch)
            self._ss = 0
            self._ur = 0
            self._st = 'TS'
        elif ch == '{' or ch == '[':
            self._vstart = pos
            self._buf = []
            self._add(ch)
            self._stk = [(ch == '{', _C_FIRST)]
            self._ins = False
            self._vk = None
            self._st = 'TC'
        elif ch == '-' or ch in _DIGIT:
            self._vstart = pos
            self._buf = []
            self._add(ch)
            self._ns = 1 if ch == '-' else (2 if ch == '0' else 3)
            self._wt = False
            self._st = 'TN'
        elif ch in _LITS:
            self._vstart = pos
            self._buf = []
            self._add(ch)
            self._lt = _LITS[ch]
            self._lp = 1
            self._wt = False
            self._st = 'TL'
        else:
            self._err(ch, pos)

    # ── TOP STRING ─────────────────────────────────────────────────────────
    def _top_str(self, ch: str, pos: int, results: list):
        self._add(ch)
        if self._ss == 0:
            if ch == '"':
                # end of string
                results.append(self._decode_buf())
                self._reset_value()
            elif ch == '\\':
                self._ss = 1
            elif ord(ch) < 0x20:
                self._err(ch, pos)
        elif self._ss == 1:
            if ch not in _ESC_CHARS:
                self._err(ch, pos)
            if ch == 'u':
                self._ss = 2
                self._ur = 4
            else:
                self._ss = 0
        else:  # ss == 2, unicode
            if ch not in _HEX:
                self._err(ch, pos)
            self._ur -= 1
            if self._ur == 0:
                self._ss = 0

    # ── TOP CONTAINER ──────────────────────────────────────────────────────
    def _top_cont(self, ch: str, pos: int, results: list):
        self._add(ch)
        if self._ins:
            self._cont_str(ch, pos)
            return
        if self._vk == _VK_NUM:
            self._cont_num(ch, pos, results)
            return
        if self._vk == _VK_LIT:
            self._cont_lit(ch, pos, results)
            return
        # structural
        self._cont_struct(ch, pos, results)

    # ── container: structural ──────────────────────────────────────────────
    def _cont_struct(self, ch: str, pos: int, results: list):
        while True:
            if ch in _WS:
                return  # skip whitespace
            if not self._stk:
                # container just closed – handled by caller
                return
            is_obj, cs = self._stk[-1]
            if cs == _C_FIRST:
                if is_obj:
                    if ch == '}':
                        self._close_cont(pos, results)
                        return
                    if ch == '"':
                        self._ins = True
                        self._ss = 0
                        self._ur = 0
                        self._vk = _VK_STR
                        return
                    self._err(ch, pos)
                else:  # array
                    if ch == ']':
                        self._close_cont(pos, results)
                        return
                    # expect a value
                    if ch == '"':
                        self._ins = True; self._ss = 0; self._ur = 0; self._vk = _VK_STR; return
                    if ch == '{' or ch == '[':
                        self._stk.append((ch == '{', _C_FIRST)); self._vk = _VK_CONT; return
                    if ch == '-' or ch in _DIGIT:
                        self._ns = 1 if ch == '-' else (2 if ch == '0' else 3)
                        self._vk = _VK_NUM; return
                    if ch in _LITS:
                        self._lt = _LITS[ch]; self._lp = 1; self._vk = _VK_LIT; return
                    self._err(ch, pos)
            elif cs == _C_COLON:
                if ch == ':':
                    self._stk[-1] = (is_obj, _C_VALUE)
                    return
                self._err(ch, pos)
            elif cs == _C_VALUE:
                if ch == '"':
                    self._ins = True; self._ss = 0; self._ur = 0; self._vk = _VK_STR; return
                if ch == '{' or ch == '[':
                    self._stk.append((ch == '{', _C_FIRST)); self._vk = _VK_CONT; return
                if ch == '-' or ch in _DIGIT:
                    self._ns = 1 if ch == '-' else (2 if ch == '0' else 3)
                    self._vk = _VK_NUM; return
                if ch in _LITS:
                    self._lt = _LITS[ch]; self._lp = 1; self._vk = _VK_LIT; return
                self._err(ch, pos)
            elif cs == _C_SEP:
                if ch == ',':
                    self._stk[-1] = (is_obj, _C_VALUE)
                    return
                if (is_obj and ch == '}') or (not is_obj and ch == ']'):
                    self._close_cont(pos, results)
                    return
                self._err(ch, pos)

    def _close_cont(self, pos: int, results: list):
        self._stk.pop()
        if not self._stk:
            # top-level container closed
            results.append(self._decode_buf())
            self._reset_value()
        else:
            # nested container closed; parent expects separator
            is_obj, _ = self._stk[-1]
            self._stk[-1] = (is_obj, _C_SEP)
            self._vk = None

    # ── container: string ──────────────────────────────────────────────────
    def _cont_str(self, ch: str, pos: int):
        if self._ss == 0:
            if ch == '"':
                self._ins = False
                self._vk = None
                # transition container to SEP (unless we're about to expect colon)
                is_obj, cs = self._stk[-1]
                if is_obj and cs == _C_FIRST:
                    self._stk[-1] = (is_obj, _C_COLON)
                else:
                    self._stk[-1] = (is_obj, _C_SEP)
            elif ch == '\\':
                self._ss = 1
            elif ord(ch) < 0x20:
                self._err(ch, pos)
        elif self._ss == 1:
            if ch not in _ESC_CHARS:
                self._err(ch, pos)
            if ch == 'u':
                self._ss = 2; self._ur = 4
            else:
                self._ss = 0
        else:
            if ch not in _HEX:
                self._err(ch, pos)
            self._ur -= 1
            if self._ur == 0:
                self._ss = 0

    # ── container: number ──────────────────────────────────────────────────
    def _cont_num(self, ch: str, pos: int, results: list):
        ns = self._ns
        if ns == 0:  # START – shouldn't happen
            self._err(ch, pos)
        elif ns == 1:  # NEG
            if ch in _DIGIT:
                self._ns = 2 if ch == '0' else 3
            else:
                self._err(ch, pos)
        elif ns == 2:  # ZERO
            if ch == '.':
                self._ns = 4
            elif ch in ('e', 'E'):
                self._ns = 6
            elif ch in _DIGIT:
                self._err(ch, pos)  # leading zero
            else:
                self._num_end(ch, pos, results)
        elif ns == 3:  # INT
            if ch in _DIGIT:
                pass  # stay in INT
            elif ch == '.':
                self._ns = 4
            elif ch in ('e', 'E'):
                self._ns = 6
            else:
                self._num_end(ch, pos, results)
        elif ns == 4:  # DOT
            if ch in _DIGIT:
                self._ns = 5
            else:
                self._err(ch, pos)
        elif ns == 5:  # FRAC
            if ch in _DIGIT:
                pass
            elif ch in ('e', 'E'):
                self._ns = 6
            else:
                self._num_end(ch, pos, results)
        elif ns == 6:  # EXP
            if ch in ('+', '-'):
                self._ns = 7
            elif ch in _DIGIT:
                self._ns = 8
            else:
                self._err(ch, pos)
        elif ns == 7:  # EXPS
            if ch in _DIGIT:
                self._ns = 8
            else:
                self._err(ch, pos)
        elif ns == 8:  # EXPD
            if ch in _DIGIT:
                pass
            else:
                self._num_end(ch, pos, results)

    def _num_end(self, ch: str, pos: int, results: list):
        """Number is complete; process ch as structural."""
        self._vk = None
        self._ns = 0
        is_obj, _ = self._stk[-1]
        self._stk[-1] = (is_obj, _C_SEP)
        # Re-process ch structurally
        self._cont_struct(ch, pos, results)

    # ── container: literal ─────────────────────────────────────────────────
    def _cont_lit(self, ch: str, pos: int, results: list):
        lt = self._lt
        lp = self._lp
        if ch != lt[lp]:
            self._err(ch, pos)
        self._lp += 1
        if self._lp == len(lt):
            # literal complete
            self._vk = None
            self._lt = None
            self._lp = 0
            is_obj, _ = self._stk[-1]
            self._stk[-1] = (is_obj, _C_SEP)

    # ── TOP NUMBER ─────────────────────────────────────────────────────────
    def _top_num(self, ch: str, pos: int, results: list):
        if self._wt:
            # number syntactically complete, waiting for terminator
            if ch in _TERM:
                results.append(self._decode_buf())
                self._reset_value()
                # re-process ch in BETWEEN
                self._between(ch, pos, results)
            else:
                self._err(ch, pos)
            return
        ns = self._ns
        if ns == 1:  # NEG
            if ch in _DIGIT:
                self._add(ch)
                self._ns = 2 if ch == '0' else 3
            else:
                self._err(ch, pos)
        elif ns == 2:  # ZERO
            if ch == '.':
                self._add(ch); self._ns = 4
            elif ch in ('e', 'E'):
                self._add(ch); self._ns = 6
            elif ch in _DIGIT:
                self._err(ch, pos)
            else:
                self._wt = True
                self._top_num_term(ch, pos, results)
        elif ns == 3:  # INT
            if ch in _DIGIT:
                self._add(ch)
            elif ch == '.':
                self._add(ch); self._ns = 4
            elif ch in ('e', 'E'):
                self._add(ch); self._ns = 6
            else:
                self._wt = True
                self._top_num_term(ch, pos, results)
        elif ns == 4:  # DOT
            if ch in _DIGIT:
                self._add(ch); self._ns = 5
            else:
                self._err(ch, pos)
        elif ns == 5:  # FRAC
            if ch in _DIGIT:
                self._add(ch)
            elif ch in ('e', 'E'):
                self._add(ch); self._ns = 6
            else:
                self._wt = True
                self._top_num_term(ch, pos, results)
        elif ns == 6:  # EXP
            if ch in ('+', '-'):
                self._add(ch); self._ns = 7
            elif ch in _DIGIT:
                self._add(ch); self._ns = 8
            else:
                self._err(ch, pos)
        elif ns == 7:  # EXPS
            if ch in _DIGIT:
                self._add(ch); self._ns = 8
            else:
                self._err(ch, pos)
        elif ns == 8:  # EXPD
            if ch in _DIGIT:
                self._add(ch)
            else:
                self._wt = True
                self._top_num_term(ch, pos, results)

    def _top_num_term(self, ch: str, pos: int, results: list):
        if ch in _TERM:
            results.append(self._decode_buf())
            self._reset_value()
            self._between(ch, pos, results)
        else:
            self._err(ch, pos)

    # ── TOP LITERAL ────────────────────────────────────────────────────────
    def _top_lit(self, ch: str, pos: int, results: list):
        if self._wt:
            if ch in _TERM:
                results.append(self._decode_buf())
                self._reset_value()
                self._between(ch, pos, results)
            else:
                self._err(ch, pos)
            return
        lt = self._lt
        lp = self._lp
        if ch != lt[lp]:
            self._err(ch, pos)
        self._add(ch)
        self._lp += 1
        if self._lp == len(lt):
            self._wt = True
```

### test_solution.py
```python
import json
import pytest
import solution
from solution import (
    JSONStreamDecoder,
    JSONStreamError,
    IncompleteJSONError,
    BufferLimitError,
)


# ── helpers ────────────────────────────────────────────────────────────────
def collect(chunks, **kw):
    d = JSONStreamDecoder(**kw)
    out = []
    for c in chunks:
        out.extend(d.feed(c))
    out.extend(d.close())
    return out


def feed_one(s, **kw):
    d = JSONStreamDecoder(**kw)
    res = d.feed(s)
    res.extend(d.close())
    return res


# ── basic values ───────────────────────────────────────────────────────────
class TestBasicValues:
    def test_integer(self):
        assert feed_one("42 ") == [42]

    def test_negative(self):
        assert feed_one("-7 ") == [-7]

    def test_float(self):
        assert feed_one("3.14 ") == [3.14]

    def test_exponent(self):
        assert feed_one("1e10 ") == [1e10]

    def test_true(self):
        assert feed_one("true ") == [True]

    def test_false(self):
        assert feed_one("false ") == [False]

    def test_null(self):
        assert feed_one("null ") == [None]

    def test_string(self):
        assert feed_one('"hello"') == ["hello"]

    def test_empty_string(self):
        assert feed_one('""') == [""]

    def test_object(self):
        assert feed_one('{"a":1}') == [{"a": 1}]

    def test_array(self):
        assert feed_one('[1,2,3]') == [[1, 2, 3]]

    def test_empty_object(self):
        assert feed_one('{}') == [{}]

    def test_empty_array(self):
        assert feed_one('[]') == [[]]

    def test_nested(self):
        assert feed_one('{"a":[1,{"b":2}]}') == [{"a": [1, {"b": 2}]}]

    def test_zero(self):
        assert feed_one("0 ") == [0]

    def test_negative_zero_float(self):
        assert feed_one("-0.0 ") == [-0.0]

    def test_large_int(self):
        n = 10**50
        assert feed_one(f"{n} ") == [n]

    def test_inf_exponent(self):
        assert feed_one("1E400 ") == [float('inf')]


# ── multiple values ────────────────────────────────────────────────────────
class TestMultipleValues:
    def test_adjacent_objects(self):
        assert feed_one('{}{}') == [{}, {}]

    def test_adjacent_mixed(self):
        assert feed_one('{}[]"x"1 ') == [{}, [], "x", 1]

    def test_numbers_with_spaces(self):
        assert feed_one("1 2 3 ") == [1, 2, 3]

    def test_no_separator_objects(self):
        assert feed_one('{"a":1}{"b":2}') == [{"a": 1}, {"b": 2}]

    def test_string_then_number(self):
        assert feed_one('"a"1 ') == ["a", 1]

    def test_number_then_string(self):
        assert feed_one('1"a"') == [1, "a"]

    def test_literal_then_object(self):
        assert feed_one('true{}') == [True, {}]

    def test_object_then_array(self):
        assert feed_one('{}[]') == [{}, []]


# ── chunking ───────────────────────────────────────────────────────────────
class TestChunking:
    def test_number_split(self):
        d = JSONStreamDecoder()
        assert d.feed("12") == []
        assert d.feed(" ") == [12]

    def test_number_char_by_char(self):
        d = JSONStreamDecoder()
        assert d.feed("1") == []
        assert d.feed("2") == []
        assert d.feed("3") == []
        assert d.feed(" ") == [123]

    def test_string_split(self):
        d = JSONStreamDecoder()
        assert d.feed('"hel') == []
        assert d.feed('lo"') == ["hello"]

    def test_escape_split(self):
        d = JSONStreamDecoder()
        assert d.feed('"a\\') == []
        assert d.feed('b"') == ["ab"]

    def test_unicode_escape_split(self):
        d = JSONStreamDecoder()
        assert d.feed('"\\u00') == []
        assert d.feed('e9"') == ["é"]

    def test_container_split(self):
        d = JSONStreamDecoder()
        assert d.feed('[1,') == []
        assert d.feed('2]') == [[1, 2]]

    def test_close_returns_number(self):
        d = JSONStreamDecoder()
        assert d.feed("42") == []
        assert d.close() == [42]

    def test_close_returns_literal(self):
        d = JSONStreamDecoder()
        assert d.feed("true") == []
        assert d.close() == [True]

    def test_empty_feed(self):
        d = JSONStreamDecoder()
        assert d.feed("") == []
        assert d.close() == []

    def test_many_values_one_chunk(self):
        text = " ".join(str(i) for i in range(1000)) + " "
        assert feed_one(text) == list(range(1000))


# ── strings with escapes ───────────────────────────────────────────────────
class TestStrings:
    def test_escapes(self):
        assert feed_one(r'"a\b\/\n\r\t"') == ["a\\/\n\r\t"]

    def test_unicode_escape(self):
        assert feed_one(r'"é"') == ["é"]

    def test_surrogate_pair(self):
        assert feed_one(r'"😀"') == ["😀"]

    def test_lone_surrogate_ok(self):
        assert feed_one(r'"\ud800"') == ["\ud800"]

    def test_backslash_quote(self):
        assert feed_one(r'"\""') == ['"']

    def test_non_bmp(self):
        assert feed_one('"𝐀"') == ["𝐀"]

    def test_u007f_ok(self):
        assert feed_one('"\x7f"') == ["\x7f"]

    def test_del_in_string(self):
        assert feed_one('"\x7f"') == ["\x7f"]


# ── errors ─────────────────────────────────────────────────────────────────
class TestErrors:
    def test_trailing_comma_array(self):
        with pytest.raises(JSONStreamError) as ei:
            feed_one("[1,]")
        assert ei.value.offset == 3

    def test_incomplete_fraction(self):
        with pytest.raises(JSONStreamError) as ei:
            feed_one("[1.]")
        assert ei.value.offset == 3

    def test_bad_literal_in_object(self):
        with pytest.raises(JSONStreamError) as ei:
            feed_one('{"a":tru}')
        assert ei.value.offset == 8

    def test_bad_escape(self):
        with pytest.raises(JSONStreamError) as ei:
            feed_one('"abc\\x"')
        assert ei.value.offset == 5

    def test_leading_zero(self):
        with pytest.raises(JSONStreamError) as ei:
            feed_one("[01]")
        assert ei.value.offset == 2

    def test_control_char_in_string(self):
        with pytest.raises(JSONStreamError) as ei:
            feed_one('"a\nb"')
